WHERE isp.status >= 0

    AND isp.status = #{filter.status}


    AND isp.date = #{filter.date}


    AND isp.location_group_id = #{filter.warehouseId}


    AND isp.reference LIKE CONCAT('%', #{filter.searchText}, '%')


    AND isp.created_by = #{userId}

